import pandas as pd
import re

def analyze_survey_responses(raw_responses, keywords):
    """
    Analyzes open-ended survey responses to categorize them into themes and assign sentiment scores.

    Args:
        raw_responses (list): A list of raw survey responses.
        keywords (dict): A dictionary containing keywords for each theme.

    Returns:
        pandas.DataFrame: A DataFrame with columns 'Response_ID', 'Primary_Theme', 'Secondary_Theme', and 'Sentiment_Score'.
    """

    data = []
    for i, response in enumerate(raw_responses):
        if response is None:
            response_text = ""
        else:
            response_text = str(response)

        themes = {}
        sentiment_score = 0

        for theme, keyword_list in keywords.items():
            for keyword in keyword_list:
                if re.search(r'\b' + keyword + r'\b', response_text, re.IGNORECASE):
                    themes[theme] = keyword
                    break  # Stop searching for keywords within a theme once one is found

        if themes:
            primary_theme = max(themes, key=themes.get)
            if len(themes) > 1:
                secondary_theme = list(themes.keys())[list(themes.values()).index(themes[primary_theme])+1]
            else:
                secondary_theme = 'Other'

            if "road" in themes or "park" in themes or "trash" in themes or "library" in themes or "building" in themes:
                sentiment_score = 1
            elif "police" in themes or "crime" in themes or "unsafe" in themes or "light" in themes:
                sentiment_score = -1
            elif "festival" in themes or "party" in themes or "gathering" in themes or "event" in themes:
                sentiment_score = 1
            elif "health" in themes or "water" in themes or "electric" in themes or "hours" in themes or "staff" in themes:
                sentiment_score = 1
            else:
                sentiment_score = 0

        else:
            primary_theme = 'Other'
            secondary_theme = 'Other'
            sentiment_score = 0

        data.append([i + 1, primary_theme, secondary_theme, sentiment_score])

    df = pd.DataFrame(data, columns=['Response_ID', 'Primary_Theme', 'Secondary_Theme', 'Sentiment_Score'])
    return df

# Example usage with the provided data
raw_responses = [
    "The roads are terrible and potholes are everywhere.",
    "I love the summer festival, it brings us together.",
    "Police presence is low, I feel unsafe at night.",
    "The library hours are inconvenient.",
    None,
    "The park is nice but the trash collection is slow."
]

keywords = {
    "Infrastructure": ["road", "bridge", "park", "trash", "library", "building"],
    "Safety": ["police", "crime", "safe", "unsafe", "light"],
    "Community Events": ["festival", "party", "gathering", "event"],
    "Services": ["health", "water", "electric", "hours", "staff"]
}

df = analyze_survey_responses(raw_responses, keywords)
print(df.to_csv(index=False))
